# -*- coding: utf-8 -*-
"""A JSON (JavaScript Object Notation) 编解码器.

这是 demjson (http://deron.meranda.us/python/demjson/) 的精简移植版本, 只保留了
mootdx 内部需要的功能, 并且底层使用标准库的 json 模块实现, 以便减少维护成本.

主要接口::

    demjson.encode(obj)             # python 对象转换为 JSON 字符串
    demjson.decode(txt)             # JSON 字符串转换为 python 对象
    demjson.encode_to_file(f, obj)  # 编码并写入文件
    demjson.decode_file(f)          # 读取文件并解码
"""
import codecs
import json
import re
import sys
from collections import namedtuple

__author__ = 'Deron Meranda <http://deron.meranda.us/>'
__credits__ = 'Short of demjson'
__date__ = '2015-12-22'
__version__ = '2.2.4'

version_info = namedtuple('version_info', ['major', 'minor', 'micro'])

__version_info__ = version_info(major=2, minor=2, micro=4)

# ----------------------------------------------------------------------
# 常量
# ----------------------------------------------------------------------
STRICTNESS_STRICT = 'strict'
STRICTNESS_WARN = 'warn'
STRICTNESS_TOLERANT = 'tolerant'

ALLOW = 'allow'
WARN = 'warn'
FORBID = 'forbid'

NUMBER_AUTO = 'auto'
NUMBER_FLOAT = 'float'
NUMBER_DECIMAL = 'decimal'

NUMBER_FORMAT_DECIMAL = 'decimal'
NUMBER_FORMAT_HEX = 'hex'
NUMBER_FORMAT_LEGACYOCTAL = 'legacyoctal'
NUMBER_FORMAT_OCTAL = 'octal'
NUMBER_FORMAT_BINARY = 'binary'

SORT_NONE = 'none'
SORT_PRESERVE = 'preserve'
SORT_ALPHA = 'alpha'
SORT_ALPHA_CI = 'alpha_ci'
SORT_SMART = 'smart'

__all__ = [
    'encode',
    'decode',
    'encode_to_file',
    'decode_file',
    'undefined',
    'json_int',
    'json_options',
    'helpers',
    'jsonlint',
    'JSONException',
    'JSONError',
    'JSONDecodeError',
    'JSONEncodeError',
    'STRICTNESS_STRICT',
    'STRICTNESS_WARN',
    'STRICTNESS_TOLERANT',
    'NUMBER_AUTO',
    'NUMBER_FLOAT',
    'NUMBER_DECIMAL',
    'SORT_NONE',
    'SORT_PRESERVE',
    'SORT_ALPHA',
    'SORT_ALPHA_CI',
    'SORT_SMART',
]


# ----------------------------------------------------------------------
# 基础帮助函数
# ----------------------------------------------------------------------
def _make_raw_bytes(byte_list):
    """Takes a list of byte values (numbers) and returns a bytes (Python 3) or string (Python 2)."""
    return bytes(bytearray(byte_list))


def _make_unsafe_string_chars():
    """不安全的字符串字符集合."""
    unsafe = []

    for cval in range(0, 0x20):
        unsafe.append(chr(cval))

    unsafe.extend(['"', '\\', ' ', ' '])

    return ''.join(unsafe)


def determine_float_limits(number_type=float):
    """Determines the precision and range of the given float type.

    Returns a named tuple with components::

        (significant_digits, max_exponent, min_exponent)
    """
    float_limits = namedtuple('float_limits', ['significant_digits', 'max_exponent', 'min_exponent'])

    if number_type is float:
        return float_limits(sys.float_info.dig, sys.float_info.max_10_exp, sys.float_info.min_10_exp)

    import decimal

    context = number_type if isinstance(number_type, decimal.Context) else decimal.getcontext()

    return float_limits(context.prec, context.Emax, context.Emin)


def determine_float_precision():
    """浮点数精度信息."""
    limits = determine_float_limits(float)

    return limits.significant_digits, limits.max_exponent, limits.min_exponent


def _nonnumber_float_constants():
    """Try to return the Nan, Infinity, and -Infinity float values."""
    return float('nan'), float('inf'), float('-inf')


nan, inf, neginf = _nonnumber_float_constants()


def skipstringsafe(s, start=0, end=None):
    """跳过字符串安全字符."""
    i = start
    end = end if end is not None else len(s)
    unsafe = helpers.unsafe_string_chars

    while i < end and s[i] not in unsafe:
        i += 1

    return i


def skipstringsafe_slow(s, start=0, end=None):
    """跳过字符串安全字符 (慢速版本)."""
    i = start
    end = end if end is not None else len(s)

    while i < end:
        char = s[i]

        if char == '"' or char == '\\' or ord(char) <= 0x1F:
            break

        i += 1

    return i


def extend_list_with_sep(orig_seq, extension_seq, sepchar=''):
    """带分隔符扩展列表."""
    if not sepchar:
        orig_seq.extend(extension_seq)
        return

    for i, x in enumerate(extension_seq):
        if i > 0:
            orig_seq.append(sepchar)

        orig_seq.append(x)


def extend_and_flatten_list_with_sep(orig_seq, extension_seq, separator=''):
    """带分隔符扩展并展开列表."""
    for i, part in enumerate(extension_seq):
        if i > 0 and separator:
            orig_seq.append(separator)

        orig_seq.extend(part)


def smart_sort_transform(key):
    """智能排序 key 转换."""
    numbers = re.compile(r'(\d+)')
    parts = numbers.split(str(key))

    return tuple(int(part) if part.isdigit() else part for part in parts if part != '')


# ----------------------------------------------------------------------
# 简单类型
# ----------------------------------------------------------------------
class _dummy_context_manager(object):
    """A context manager that does nothing on entry or exit."""

    def __enter__(self):
        pass

    def __exit__(self, exc_type, exc_val, exc_tb):
        return False


class _undefined_class(object):
    """Represents the ECMAScript 'undefined' value."""

    __slots__ = []

    def __repr__(self):
        return self.__module__ + '.undefined'

    def __str__(self):
        return 'undefined'

    def __bool__(self):
        return False

    __nonzero__ = __bool__


undefined = _undefined_class()
syntax_error = _undefined_class()


class json_int(int):
    """A subclass of the Python int that remembers its format (hex, octal, etc)."""

    def __new__(cls, *args, **kwargs):
        number_format = kwargs.pop('number_format', NUMBER_FORMAT_DECIMAL)
        obj = super().__new__(cls, *args, **kwargs)
        obj._number_format = number_format

        return obj

    @property
    def number_format(self):
        """The original radix format of the number."""
        return self._number_format

    def json_format(self):
        """Returns the integer value formatted as a JSON literal."""
        fmt = self._number_format

        if fmt == NUMBER_FORMAT_HEX:
            return f'{"-" if self < 0 else ""}0x{abs(int(self)):x}'

        if fmt == NUMBER_FORMAT_OCTAL:
            return f'{"-" if self < 0 else ""}0o{abs(int(self)):o}'

        if fmt == NUMBER_FORMAT_LEGACYOCTAL:
            return f'{"-" if self < 0 else ""}0{abs(int(self)):o}'

        if fmt == NUMBER_FORMAT_BINARY:
            return f'{"-" if self < 0 else ""}0b{abs(int(self)):b}'

        return f'{int(self):d}'


class utf32(codecs.CodecInfo):
    """Unicode UTF-32 and UCS4 encoding/decoding support."""

    BOM_UTF32_BE = _make_raw_bytes([0, 0, 0xFE, 0xFF])
    BOM_UTF32_LE = _make_raw_bytes([0xFF, 0xFE, 0, 0])

    @staticmethod
    def lookup(name):
        """A standard Python codec lookup function for UCS4/UTF32."""
        if str(name).lower().replace('_', '-') in ('utf-32', 'ucs4', 'ucs-4', 'utf32'):
            return codecs.lookup('utf-32')

        return None

    @staticmethod
    def encode(obj, errors='strict', endianness=None, include_bom=True):
        """Encodes a Unicode string into a UTF-32 encoded byte string."""
        encoding = utf32._encoding(endianness, include_bom)

        return obj.encode(encoding, errors), len(obj)

    @staticmethod
    def utf32le_encode(obj, errors='strict', include_bom=False):
        """Encodes a Unicode string into a UTF-32LE (little endian) encoded byte string."""
        return obj.encode('utf-32-le', errors), len(obj)

    @staticmethod
    def utf32be_encode(obj, errors='strict', include_bom=False):
        """Encodes a Unicode string into a UTF-32BE (big endian) encoded byte string."""
        return obj.encode('utf-32-be', errors), len(obj)

    @staticmethod
    def decode(obj, errors='strict', endianness=None):
        """Decodes a UTF-32 byte string into a Unicode string."""
        encoding = utf32._encoding(endianness, True)

        return obj.decode(encoding, errors), len(obj)

    @staticmethod
    def utf32le_decode(obj, errors='strict'):
        """Decodes a UTF-32LE (little endian) byte string into a Unicode string."""
        return obj.decode('utf-32-le', errors), len(obj)

    @staticmethod
    def utf32be_decode(obj, errors='strict'):
        """Decodes a UTF-32BE (big endian) byte string into a Unicode string."""
        return obj.decode('utf-32-be', errors), len(obj)

    @staticmethod
    def _encoding(endianness=None, include_bom=True):
        """内部方法, 计算编码名称."""
        if not endianness:
            return 'utf-32' if include_bom else f'utf-32-{"le" if sys.byteorder == "little" else "be"}'

        endianness = str(endianness)[0].upper()

        if endianness in ('B', '>'):
            return 'utf-32-be'

        if endianness in ('L', '<'):
            return 'utf-32-le'

        return 'utf-32'


class helpers(object):
    """A set of utility functions."""

    hexdigits = '0123456789ABCDEFabcdef'
    octaldigits = '01234567'
    unsafe_string_chars = _make_unsafe_string_chars()

    maxunicode = sys.maxunicode

    always_use_custom_codecs = False

    javascript_reserved_words = frozenset(
        [
            'break', 'case', 'catch', 'class', 'const', 'continue',
            'debugger', 'default', 'delete', 'do', 'else', 'export',
            'extends', 'finally', 'for', 'function', 'if', 'import',
            'in', 'instanceof', 'let', 'new', 'return', 'super',
            'switch', 'this', 'throw', 'try', 'typeof', 'var', 'void',
            'while', 'with', 'yield',
            'enum', 'implements', 'interface', 'package',
            'private', 'protected', 'public', 'static',
            'null', 'true', 'false',
        ]
    )  # fmt: skip

    @staticmethod
    def make_raw_bytes(byte_list):
        """Constructs a byte array from a list of byte values (0-255)."""
        return _make_raw_bytes(byte_list)

    @staticmethod
    def is_hex_digit(c):
        """Determines if the given character is a valid hexadecimal digit."""
        return c in helpers.hexdigits

    @staticmethod
    def is_octal_digit(c):
        """Determines if the given character is a valid octal digit (0-7)."""
        return c in helpers.octaldigits

    @staticmethod
    def is_binary_digit(c):
        """Determines if the given character is a valid binary digit (0 or 1)."""
        return c in ('0', '1')

    @staticmethod
    def char_is_json_ws(c):
        """Determines if the given character is a JSON white-space character."""
        return c in ' \t\n\r'

    @staticmethod
    def safe_unichr(codepoint):
        """Just like Python's unichr() but works in narrow-Unicode Pythons."""
        return chr(codepoint)

    @staticmethod
    def char_is_unicode_ws(c):
        """Determines if the given character is a Unicode space character."""
        if not isinstance(c, str):
            return False

        if c in ' \t\n\r\f\v':
            return True

        import unicodedata

        return unicodedata.category(c) == 'Zs'

    @staticmethod
    def char_is_json_eol(c):
        """Determines if the given character is a JSON line separator."""
        return c in '\n\r'

    @staticmethod
    def char_is_unicode_eol(c):
        """Determines if the given character is a Unicode line or paragraph separator."""
        return c in '\r\n  '

    @staticmethod
    def char_is_identifier_leader(c):
        """Determines if the character may be the first character of an identifier."""
        return c.isalpha() or c in '_$'

    @staticmethod
    def char_is_identifier_tail(c):
        """Determines if the character may be part of an identifier."""
        return c.isalnum() or c in '_$‌‍'

    @staticmethod
    def extend_and_flatten_list_with_sep(orig_seq, extension_seq, separator=''):
        """带分隔符扩展并展开列表."""
        return extend_and_flatten_list_with_sep(orig_seq, extension_seq, separator)

    @staticmethod
    def strip_format_control_chars(txt):
        """Filters out all Unicode format control characters from the string."""
        import unicodedata

        return ''.join([c for c in txt if unicodedata.category(c) != 'Cf'])

    @staticmethod
    def lookup_codec(encoding):
        """Wrapper around codecs.lookup(), returns None if codec is not found."""
        if isinstance(encoding, codecs.CodecInfo):
            return encoding

        try:
            return codecs.lookup(encoding)
        except LookupError:
            return utf32.lookup(encoding)

    @staticmethod
    def auto_detect_encoding(s):
        """Tries to determine the Unicode encoding of the given byte array."""
        if not isinstance(s, (bytes, bytearray)):
            return 'utf-8'

        if s.startswith(codecs.BOM_UTF8):
            return 'utf-8-sig'

        if s.startswith(utf32.BOM_UTF32_LE):
            return 'utf-32-le'

        if s.startswith(utf32.BOM_UTF32_BE):
            return 'utf-32-be'

        if s.startswith(codecs.BOM_UTF16_LE):
            return 'utf-16-le'

        if s.startswith(codecs.BOM_UTF16_BE):
            return 'utf-16-be'

        head = bytes(s[:4])

        if len(head) >= 4:
            if head[0] == 0 and head[1] == 0 and head[2] == 0:
                return 'utf-32-be'

            if head[1] == 0 and head[2] == 0 and head[3] == 0:
                return 'utf-32-le'

            if head[0] == 0 and head[2] == 0:
                return 'utf-16-be'

            if head[1] == 0 and head[3] == 0:
                return 'utf-16-le'

        return 'utf-8'

    @staticmethod
    def unicode_decode(txt, encoding=None):
        """Takes a string (or byte array) and tries to convert it to a Unicode string."""
        decoded = namedtuple('unicode_decode', ['string', 'codec', 'bom'])

        if isinstance(txt, str):
            return decoded(txt, None, None)

        if not encoding or encoding == 'auto':
            encoding = helpers.auto_detect_encoding(txt)

        codec = helpers.lookup_codec(encoding)
        bom = b''

        for marker in (codecs.BOM_UTF8, utf32.BOM_UTF32_LE, utf32.BOM_UTF32_BE, codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE):
            if bytes(txt).startswith(marker):
                bom = marker
                break

        return decoded(bytes(txt).decode(encoding, 'replace'), codec, bom)

    @staticmethod
    def surrogate_pair_as_unicode(c1, c2):
        """Takes a pair of unicode surrogates and returns the equivalent unicode character."""
        n1, n2 = ord(c1), ord(c2)

        if n1 < 0xD800 or n1 > 0xDBFF or n2 < 0xDC00 or n2 > 0xDFFF:
            raise JSONDecodeError('illegal UTF-16 surrogate pair', data=(c1, c2))

        return chr(0x10000 + (((n1 - 0xD800) << 10) | (n2 - 0xDC00)))

    @staticmethod
    def unicode_as_surrogate_pair(c):
        """Takes a single unicode character and returns a sequence of surrogate pairs."""
        n = ord(c)

        if n < 0x10000:
            return (chr(n),)

        return tuple(chr(x) for x in helpers.make_surrogate_pair(n))

    @staticmethod
    def make_surrogate_pair(codepoint):
        """Given a Unicode codepoint (int) returns a 2-tuple of surrogate codepoints."""
        if codepoint < 0x10000:
            return codepoint, None

        codepoint -= 0x10000

        return 0xD800 + (codepoint >> 10), 0xDC00 + (codepoint & 0x3FF)

    @staticmethod
    def isnumbertype(obj):
        """Is the object of a Python number type (excluding complex)?"""
        return isinstance(obj, (int, float)) and not isinstance(obj, bool)

    @staticmethod
    def is_negzero(n):
        """Is the number value a negative zero?"""
        return n == 0.0 and str(n)[0] == '-'

    @staticmethod
    def is_nan(n):
        """Is the number a NaN (not-a-number)?"""
        return n != n

    @staticmethod
    def is_infinite(n):
        """Is the number infinite?"""
        return n == inf or n == neginf

    @staticmethod
    def isstringtype(obj):
        """Is the object of a Python string type?"""
        return isinstance(obj, (str, bytes, bytearray))

    @staticmethod
    def decode_hex(hexstring):
        """Decodes a hexadecimal string into it's integer value."""
        return int(hexstring, 16)

    @staticmethod
    def decode_octal(octalstring):
        """Decodes an octal string into it's integer value."""
        return int(octalstring, 8)

    @staticmethod
    def decode_binary(binarystring):
        """Decodes a binary string into it's integer value."""
        return int(binarystring, 2)

    @staticmethod
    def format_timedelta_iso(td):
        """Encodes a datetime.timedelta into ISO-8601 Time Period format."""
        days = td.days
        hours, remainder = divmod(td.seconds, 3600)
        minutes, seconds = divmod(remainder, 60)

        if td.microseconds:
            seconds = seconds + td.microseconds / 1000000.0

        return f'P{days}DT{hours}H{minutes}M{seconds}S'


# ----------------------------------------------------------------------
# 异常
# ----------------------------------------------------------------------
class JSONException(Exception):
    """Base class for all JSON-related exceptions."""


class JSONSkipHook(JSONException):
    """Raised by user hooks that do not want to handle a situation."""


class JSONStopProcessing(JSONException):
    """Raised to stop the encode or decode process immediately."""


class JSONAbort(JSONException):
    """Raised to abort processing."""


class JSONError(JSONException):
    """Base class for all JSON-related errors."""

    severities = frozenset(['fatal', 'error', 'warning', 'info'])

    def __init__(self, message, *args, **kwargs):
        self.severity = 'error'
        self._position = None
        self.outer_position = None
        self.context_description = None

        for kw, val in list(kwargs.items()):
            if kw == 'severity':
                if val not in self.severities:
                    raise TypeError(f'{self.__class__.__name__} given invalid severity {val!r}')

                self.severity = val
            elif kw == 'position':
                self.position = val
            elif kw == 'outer_position':
                self.outer_position = val
            elif kw in ('context_description', 'context'):
                self.context_description = val
            elif kw == 'data':
                self.data = val
            else:
                raise TypeError(f'{self.__class__.__name__} does not accept {kw!r} keyword argument')

        super().__init__(message, *args)

        self.message = message

    @property
    def position(self):
        """错误位置."""
        return self._position

    @position.setter
    def position(self, pos):
        self._position = pos

    def __repr__(self):
        return f'<{self.__class__.__name__} {self.severity}: {self.message}>'

    def pretty_description(self, show_positions=True, filename=None):
        """格式化的错误描述."""
        parts = [f'{self.severity}:']

        filename and parts.append(f'{filename}:')

        if show_positions and self._position is not None:
            parts.append(f'{self._position}:')

        parts.append(self.message)

        return ' '.join(parts)


class JSONDecodeError(JSONError):
    """An exception class raised when a JSON decoding error (syntax error) occurs."""


class JSONDecodeHookError(JSONDecodeError):
    """An exception that occurred within a decoder hook."""

    def __init__(self, hook_name, exc_info, encoded_obj, *args, **kwargs):
        self.hook_name = hook_name

        if not exc_info:
            exc_info = (None, None, None)

        _exc_type, self.hook_exception, self.hook_traceback = exc_info
        self.object_type = type(encoded_obj)

        msg = 'Hook %s raised %r while decoding type <%s>' % (
            hook_name,
            self.hook_exception.__class__.__name__,
            self.object_type.__name__,
        )

        if len(args) >= 1:
            msg += ': ' + args[0]
            args = args[1:]

        super().__init__(msg, *args, **kwargs)


class JSONEncodeError(JSONError):
    """An exception class raised when a python object can not be encoded as a JSON string."""


class JSONEncodeHookError(JSONEncodeError):
    """An exception that occurred within an encoder hook."""

    def __init__(self, hook_name, exc_info, encoded_obj, *args, **kwargs):
        self.hook_name = hook_name

        if not exc_info:
            exc_info = (None, None, None)

        _exc_type, self.hook_exception, self.hook_traceback = exc_info
        self.object_type = type(encoded_obj)

        msg = 'Hook %s raised %r while encoding type <%s>' % (
            self.hook_name,
            self.hook_exception.__class__.__name__,
            self.object_type.__name__,
        )

        if len(args) >= 1:
            msg += ': ' + args[0]
            args = args[1:]

        super().__init__(msg, *args, **kwargs)


# ----------------------------------------------------------------------
# 位置与缓冲流
# ----------------------------------------------------------------------
class position_marker(object):
    """A position marks a specific place in a text document."""

    def __init__(self, offset=0, line=1, column=0, text_after=None):
        self.__char_position = offset
        self.__line = line
        self.__column = column
        self.__text_after = text_after
        self.__at_end = False
        self.__last_was_cr = False

    @property
    def line(self):
        """The current line within the document, starts at 1."""
        return self.__line

    @property
    def column(self):
        """The current character column, starts at 0."""
        return self.__column

    @property
    def char_position(self):
        """The current character offset, starts at 0."""
        return self.__char_position

    @property
    def at_start(self):
        """Returns True if the position is at the start of the document."""
        return self.__char_position == 0

    @property
    def at_end(self):
        """Returns True if the position is at the end of the document."""
        return self.__at_end

    @at_end.setter
    def at_end(self, b):
        self.__at_end = bool(b)

    @property
    def text_after(self):
        """Returns a textual excerpt starting at the current position."""
        return self.__text_after

    @text_after.setter
    def text_after(self, value):
        self.__text_after = value

    def __repr__(self):
        return f'<position_marker line={self.line} column={self.column} char={self.char_position}>'

    def describe(self, show_text=True):
        """Returns a human-readable description of the position, in English."""
        desc = f'line {self.line}, column {self.column}, offset {self.char_position}'

        if show_text and self.__text_after:
            desc += f', text {self.__text_after!r}'

        return desc

    def __str__(self):
        return self.describe()

    def copy(self):
        """Create a copy of the position object."""
        other = position_marker(self.__char_position, self.__line, self.__column, self.__text_after)
        other.at_end = self.__at_end

        return other

    def rewind(self):
        """Set the position to the start of the document."""
        self.__char_position = 0
        self.__line = 1
        self.__column = 0
        self.__at_end = False
        self.__last_was_cr = False

    def advance(self, s):
        """Advance the position according to the given string of characters."""
        for c in s:
            self.__char_position += 1

            if c == '\r':
                self.__line += 1
                self.__column = 0
                self.__last_was_cr = True
                continue

            if c == '\n':
                if not self.__last_was_cr:
                    self.__line += 1

                self.__column = 0
                self.__last_was_cr = False
                continue

            self.__last_was_cr = False
            self.__column += 1


class buffered_stream(object):
    """A helper class for the JSON parser."""

    def __init__(self, txt='', encoding=None):
        self.reset()
        self.set_text(txt, encoding)

    def reset(self):
        """Clears the state to nothing."""
        self.__test = ''
        self.__string = ''
        self.__codec = None
        self.__bom = b''
        self.__pos = position_marker()
        self.__saved_pos = []

    def save_position(self):
        """保存当前位置."""
        self.__saved_pos.append(self.__pos.copy())

        return True

    def clear_saved_position(self):
