            count += 1

        return count

    def skipwhile(self, testfn):
        """Advances the current position while testfn succeeds."""
        return self.skipuntil(lambda c: not testfn(c))

    def skip_to_next_line(self, allow_unicode_eol=True):
        """Advances the current position to the start of the next line."""
        while not self.at_end and not self.at_eol(allow_unicode_eol):
            self.skip()

        if self.startswith('\r\n'):
