        return s

    def popif(self, testfn):
        """Just like pop() but only if the predicate succeeds."""
        c = self.peek()

        if c and testfn(c):
            return self.pop()

        return ''

    def pop_while_in(self, chars):
        """Pops a sequence of characters while each of them is in chars."""
        result = []

        while self.peek() and self.peek() in chars:
            result.append(self.pop())

        return ''.join(result)

    def pop_identifier(self, match=None):
        """Pops a JavaScript identifier at the current position."""
        if not self.peek() or not helpers.char_is_identifier_leader(self.peek()):
            return ''

        result = [self.pop()]

        while self.peek() and helpers.char_is_identifier_tail(self.peek()):
            result.append(self.pop())

        return ''.join(result)

    def pop_if_startswith(self, s):
        """Pops the sequence of characters if they match the given string."""
        if not self.startswith(s):
            return ''

        return self.popstr(len(s))

    def popwhile(self, testfn, maxchars=None):
        """Pops all the characters while testfn succeeds."""
        result = []

        while self.peek() and testfn(self.peek()):
            if maxchars is not None and len(result) >= maxchars:
                break

            result.append(self.pop())

        return ''.join(result)

    def popuntil(self, testfn, maxchars=None):
        """Just like popwhile() except testfn should return True to stop."""
        return self.popwhile(lambda c: not testfn(c), maxchars=maxchars)

    def __getitem__(self, index):
        if isinstance(index, slice):
            start = self.cpos + (index.start or 0)
            stop = self.cpos + index.stop if index.stop is not None else len(self.__string)

            return self.__string[start:stop]

        if index < 0:
            pos = self.cpos + index

            return self.__string[pos] if pos >= 0 else ''

        return self.peek(index)


