class decode_state(object):
    """An internal transient object used during JSON decoding."""

    def __init__(self, options=None):
        self.reset()
        self.options = options

    def reset(self):
        """Clears all errors, statistics, and input text."""
        self.stats = decode_statistics()
        self.errors = []
        self.stack = []
        self.stream = None
        self.obj = None

    @property
    def should_stop(self):
        """是否应该停止处理."""
        return self.has_fatal

    @property
    def has_errors(self):
        """Have any errors been seen already?"""
        return any(e.severity in ('fatal', 'error') for e in self.errors)

    @property
    def has_fatal(self):
        """Have any fatal errors been seen already?"""
        return any(e.severity == 'fatal' for e in self.errors)

    def set_input(self, txt, encoding=None):
        """Initialize the state by setting the input document text."""
        self.stream = buffered_stream(txt, encoding=encoding)

        return self.stream

    def push_exception(self, exc):
        """Add an already-built exception to the error list."""
        self.errors.append(exc)

    def push_fatal(self, message, *args, **kwargs):
        """Create a fatal error."""
        kwargs['severity'] = 'fatal'
        self.__push_err(message, *args, **kwargs)

    def push_error(self, message, *args, **kwargs):
        """Create an error."""
        kwargs['severity'] = 'error'
        self.__push_err(message, *args, **kwargs)

    def push_warning(self, message, *args, **kwargs):
        """Create a warning."""
        kwargs['severity'] = 'warning'
        self.__push_err(message, *args, **kwargs)

    def push_info(self, message, *args, **kwargs):
        """Create an informational message."""
        kwargs['severity'] = 'info'
        self.__push_err(message, *args, **kwargs)

    def push_cond(self, behavior_value, message, *args, **kwargs):
        """Creates a conditional error or warning message."""
        if behavior_value == ALLOW:
            return None

        if behavior_value == WARN:
            return self.push_warning(message, *args, **kwargs)

        return self.push_error(message, *args, **kwargs)

    def __push_err(self, message, *args, **kwargs):
        """Stores an error in the error list."""
        self.errors.append(JSONDecodeError(message, *args, **kwargs))

    def update_depth_stats(self, **kwargs):
        """更新深度统计."""
        self.stats.max_depth = max(self.stats.max_depth, len(self.stack))

    def update_string_stats(self, s, **kwargs):
        """更新字符串统计."""
        self.stats.num_strings += 1
        self.stats.max_string_length = max(self.stats.max_string_length, len(s))
        self.stats.total_string_length += len(s)

    def update_negzero_int_stats(self, **kwargs):
        """更新负零整数统计."""
        self.stats.num_negative_zero_ints += 1

    def update_negzero_float_stats(self, **kwargs):
        """更新负零浮点统计."""
        self.stats.num_negative_zero_floats += 1

    def update_float_stats(self, float_value, **kwargs):
        """更新浮点统计."""
        self.stats.num_floats += 1

    def update_integer_stats(self, int_value, **kwargs):
        """更新整数统计."""
        self.stats.num_ints += 1


class json_options(object):
    """Options to determine how strict the decoder or encoder should be."""

    def __init__(self, **kwargs):
        self.reset_to_defaults()

        for key, value in kwargs.items():
            if key == 'strict':
                self.strictness = value
            else:
                setattr(self, key, value)

    def reset_to_defaults(self):
        """恢复默认配置."""
        self._strictness = STRICTNESS_TOLERANT
        self._sort_keys = SORT_ALPHA
        self._encode_enum_as = 'name'
        self._leading_zero_radix = 8

        self.compactly = True
        self.escape_unicode = False
        self.allow_or_warn_behaviors = frozenset()
        self.indent_amount = 2
        self.indent_tab_width = 0
        self.indent_limit = None
        self.date_format = 'iso'
        self.html_safe = False
        self.keep_format = False
        self.warnings = True
        self.decimal_context = None

        return self

    def copy(self):
        """复制配置对象."""
        other = json_options()
        other.copy_from(self)

        return other

    def copy_from(self, other):
        """从另外一个配置对象复制."""
        self.__dict__.update({k: v for k, v in other.__dict__.items()})

        return self

    def spaces_to_next_indent_level(self, min_spaces=1, subtract=0):
        """下一级缩进的空格数."""
        return max(min_spaces, self.indent_amount - subtract)

    def indentation_for_level(self, level=0):
        """Returns a whitespace string used for indenting."""
        if self.compactly:
            return ''

        limit = self.indent_limit

        if limit is not None:
            level = min(level, limit)

        return ' ' * (level * self.indent_amount)

    def set_indent(self, num_spaces, tab_width=0, limit=None):
        """Changes the indentation properties."""
        self.indent_amount = num_spaces
        self.indent_tab_width = tab_width
        self.indent_limit = limit
        self.compactly = not num_spaces

        return self

    @property
    def sort_keys(self):
        """The method used to sort dictionary keys when encoding JSON."""
        return self._sort_keys

    @sort_keys.setter
    def sort_keys(self, method):
        self._sort_keys = method

    @property
    def encode_enum_as(self):
        """The strategy for encoding Python Enum values."""
        return self._encode_enum_as

    @encode_enum_as.setter
    def encode_enum_as(self, val):
        if val not in ('name', 'qname', 'value'):
            raise ValueError("encode_enum_as must be one of 'name','qname', or 'value'")

        self._encode_enum_as = val

    @property
    def zero_float(self):
        """The numeric value 0.0."""
        return 0.0

    @property
    def negzero_float(self):
        """The numeric value -0.0."""
        return -0.0

    @property
    def nan(self):
        """The numeric value NaN."""
        return nan

    @property
    def inf(self):
        """The numeric value Infinity."""
        return inf

    @property
    def neginf(self):
        """The numeric value -Infinity."""
        return neginf

    def make_int(self, s, sign=None, number_format=NUMBER_FORMAT_DECIMAL):
        """Makes an integer value according to the current options."""
        if isinstance(s, str):
            radix = {
                NUMBER_FORMAT_HEX: 16,
                NUMBER_FORMAT_OCTAL: 8,
                NUMBER_FORMAT_LEGACYOCTAL: 8,
                NUMBER_FORMAT_BINARY: 2,
            }.get(number_format, 10)

            value = int(s, radix)
        else:
            value = int(s)

        if sign == '-':
            value = -value

        return json_int(value, number_format=number_format)

    def make_decimal(self, s, sign='+'):
        """Converts a string into a decimal or float value."""
        import decimal

        value = decimal.Decimal(s)

        return -value if sign == '-' else value

    def make_float(self, s, sign='+'):
        """Converts a string into a float or decimal value."""
        value = float(s)

        return -value if sign == '-' else value

    @property
    def leading_zero_radix(self):
        """The radix to be used for numbers with leading zeros. 8 or 10."""
        return self._leading_zero_radix

    @leading_zero_radix.setter
    def leading_zero_radix(self, radix):
        if int(radix) not in (8, 10):
            raise ValueError('leading_zero_radix must be 8 or 10')

        self._leading_zero_radix = int(radix)

    @property
    def leading_zero_radix_as_word(self):
        """The radix name for numbers with leading zeros."""
        return {8: 'octal', 10: 'decimal'}[self._leading_zero_radix]

    def suppress_warnings(self):
        """关闭警告."""
        self.warnings = False

        return self

    @property
    def strictness(self):
        """严格模式."""
        return self._strictness

    @strictness.setter
    def strictness(self, strict):
        if strict is True:
            self._strictness = STRICTNESS_STRICT
        elif strict is False:
            self._strictness = STRICTNESS_TOLERANT
        else:
            self._strictness = strict


# ----------------------------------------------------------------------
# 编解码函数
# ----------------------------------------------------------------------
def _tolerant_json(txt: str) -> str:
    """将宽松的 javascript 对象字面量转换为标准 JSON."""
    # 去掉注释
    txt = re.sub(r'/\*.*?\*/', '', txt, flags=re.S)
    txt = re.sub(r'(^|[^:"\'\\])//[^\n\r]*', r'\1', txt)

    # 去掉尾部多余的逗号
    txt = re.sub(r',\s*([}\]])', r'\1', txt)

    # 单引号转双引号
    txt = re.sub(r"'([^'\"]*)'", r'"\1"', txt)

    # 没有引号的 key
    txt = re.sub(r'([{,]\s*)([A-Za-z_$][A-Za-z_$0-9]*)(\s*:)', r'\1"\2"\3', txt)

    return txt


def decode(txt, encoding=None, **kwargs):
    """Decodes a JSON-encoded string into a Python object.

    :param txt: JSON 字符串
    :param encoding: 字符编码
    :return: python 对象
    """
    if isinstance(txt, (bytes, bytearray)):
        encoding = encoding or helpers.auto_detect_encoding(txt)
        txt = bytes(txt).decode(encoding, 'replace')

    if txt is None:
        raise JSONDecodeError('Can not decode a None object')

    txt = txt.lstrip('﻿').strip()
    strict = kwargs.get('strict', False)

    try:
        return json.loads(txt)
    except ValueError as e:
        if strict:
            raise JSONDecodeError(str(e))

    try:
        return json.loads(_tolerant_json(txt))
    except ValueError as e:
        raise JSONDecodeError(str(e))


def encode(obj, encoding=None, **kwargs):
    """Encodes a Python object into a JSON-encoded string.

    :param obj: python 对象
    :param encoding: 字符编码, 若指定则返回 bytes
    :return: str or bytes
    """
    compactly = kwargs.get('compactly', True)
    escape_unicode = kwargs.get('escape_unicode', False)
    sort_keys = kwargs.get('sort_keys', SORT_NONE)

    separators = (',', ':') if compactly else (', ', ': ')

    result = json.dumps(
        obj,
        ensure_ascii=bool(escape_unicode),
        indent=None if compactly else 2,
        separators=separators,
        sort_keys=sort_keys in (SORT_ALPHA, SORT_ALPHA_CI, True),
        default=str,
    )

    if encoding:
        return result.encode(encoding)

    return result


def encode_to_file(filename, obj, encoding='utf-8', overwrite=False, **kwargs):
    """Encodes a Python object into JSON and writes into the given file.

    :param filename: 文件名
    :param obj: python 对象
    :param encoding: 字符编码
    :param overwrite: 是否覆盖已有文件
    """
    import os

    if not overwrite and os.path.exists(filename):
        raise IOError(f'File already exists: {filename}')

    content = encode(obj, **kwargs)

    with open(filename, 'wb') as fp:
        fp.write(content.encode(encoding or 'utf-8'))

    return True


def decode_file(filename, encoding=None, **kwargs):
    """Decodes JSON found in the given file.

    :param filename: 文件名
    :param encoding: 字符编码
    :return: python 对象
    """
    with open(filename, 'rb') as fp:
        content = fp.read()

    return decode(content, encoding=encoding, **kwargs)


class jsonlint(object):
    """This class contains most of the logic for the "jsonlint" command."""

    SUCCESS_FAIL = 'E'
    SUCCESS_WARNING = 'W'
    SUCCESS_OK = 'OK'

    _jsonlint_usage = """Usage: %(program_name)s [<options> ...] [--] inputfile.json ...

With no input filename, or "-", it will read from standard input.
"""

    def __init__(self, program_name='jsonlint', stdin=None, stdout=None, stderr=None):
        import os

        self.program_path = program_name
        self.program_name = os.path.basename(program_name)

        self.stdin = stdin or sys.stdin
        self.stdout = stdout or sys.stdout
        self.stderr = stderr or sys.stderr

    @property
    def usage(self):
        """A multi-line string containing the program usage instructions."""
        return self._jsonlint_usage % {
            'program_name': self.program_name,
            'sort_options_help': '',
            'homepage': __homepage__ if '__homepage__' in globals() else '',
        }

    def _lintcheck_data(self, jsondata, verbose_fp=None, reformat=False, show_stats=False, **kwargs):
        """检查 JSON 数据."""
        try:
            obj = decode(jsondata)
        except JSONError as e:
            verbose_fp and verbose_fp.write(f'{e}\n')

            return self.SUCCESS_FAIL, None

        return self.SUCCESS_OK, (encode(obj, compactly=not reformat) if reformat else None)

    def _lintcheck(self, filename, output_filename, verbose=False, reformat=False, show_stats=False, **kwargs):
        """检查 JSON 文件."""
        if not filename or filename == '-':
            content = self.stdin.read()
        else:
            with open(filename, 'rb') as fp:
                content = fp.read()

        status, result = self._lintcheck_data(
            content, verbose_fp=self.stderr if verbose else None, reformat=reformat, show_stats=show_stats
        )

        if result:
            if output_filename:
                with open(output_filename, 'w', encoding='utf-8') as fp:
                    fp.write(result)
            else:
                self.stdout.write(result + '\n')

        return status

    def main(self, argv):
        """The main routine for program "jsonlint"."""
        argv = list(argv or [])

        if '-h' in argv or '--help' in argv:
            self.stdout.write(self.usage)

            return 0

        reformat = '-f' in argv or '--format' in argv
        argv = [a for a in argv if not a.startswith('-')]

        results = [self._lintcheck(name or '-', None, reformat=reformat) for name in (argv or ['-'])]

        return 0 if all(r == self.SUCCESS_OK for r in results) else 1


__homepage__ = 'http://deron.meranda.us/python/demjson/'


def main(argv=None):  # pragma: no cover
    """命令行入口."""
    lint = jsonlint(argv[0] if argv else 'jsonlint')

    return lint.main(argv[1:] if argv else [])


if __name__ == '__main__':  # pragma: no cover
    sys.exit(main(sys.argv))

