        self.stats = decode_statistics()
        self.errors = []
        self.stack = []
        self.stream = None
        self.obj = None

    @property
    def should_stop(self):
        """是否应该停止处理."""
        return self.has_fatal

    @property
    def has_errors(self):
        """Have any errors been seen already?"""
        return any(e.severity in ('fatal', 'error') for e in self.errors)

    @property
    def has_fatal(self):
        """Have any fatal errors been seen already?"""
        return any(e.severity == 'fatal' for e in self.errors)

    def set_input(self, txt, encoding=None):
        """Initialize the state by setting the input document text."""
        self.stream = buffered_stream(txt, encoding=encoding)

        return self.stream

    def push_exception(self, exc):
        """Add an already-built exception to the error list."""
        self.errors.append(exc)

    def push_fatal(self, message, *args, **kwargs):
        """Create a fatal error."""
        kwargs['severity'] = 'fatal'
        self.__push_err(message, *args, **kwargs)

    def push_error(self, message, *args, **kwargs):
        """Create an error."""
        kwargs['severity'] = 'error'
        self.__push_err(message, *args, **kwargs)

    def push_warning(self, message, *args, **kwargs):
        """Create a warning."""
        kwargs['severity'] = 'warning'
        self.__push_err(message, *args, **kwargs)

    def push_info(self, message, *args, **kwargs):
        """Create an informational message."""
        kwargs['severity'] = 'info'
        self.__push_err(message, *args, **kwargs)

    def push_cond(self, behavior_value, message, *args, **kwargs):
        """Creates a conditional error or warning message."""
        if behavior_value == ALLOW:
            return None

        if behavior_value == WARN:
            return self.push_warning(message, *args, **kwargs)

        return self.push_error(message, *args, **kwargs)

    def __push_err(self, message, *args, **kwargs):
        """Stores an error in the error list."""
        self.errors.append(JSONDecodeError(message, *args, **kwargs))

    def update_depth_stats(self, **kwargs):
        """更新深度统计."""
        self.stats.max_depth = max(self.stats.max_depth, len(self.stack))

    def update_string_stats(self, s, **kwargs):
        """更新字符串统计."""
        self.stats.num_strings += 1
        self.stats.max_string_length = max(self.stats.max_string_length, len(s))
        self.stats.total_string_length += len(s)

    def update_negzero_int_stats(self, **kwargs):
        """更新负零整数统计."""
        self.stats.num_negative_zero_ints += 1

    def update_negzero_float_stats(self, **kwargs):
        """更新负零浮点统计."""
        self.stats.num_negative_zero_floats += 1

    def update_float_stats(self, float_value, **kwargs):
        """更新浮点统计."""
        self.stats.num_floats += 1

    def update_integer_stats(self, int_value, **kwargs):
        """更新整数统计."""
        self.stats.num_ints += 1


class json_options(object):
    """Options to determine how strict the decoder or encoder should be."""

    def __init__(self, **kwargs):
        self.reset_to_defaults()

        for key, value in kwargs.items():
            if key == 'strict':
                self.strictness = value
            else:
                setattr(self, key, value)

    def reset_to_defaults(self):
        """恢复默认配置."""
        self._strictness = STRICTNESS_TOLERANT
        self._sort_keys = SORT_ALPHA
        self._encode_enum_as = 'name'
        self._leading_zero_radix = 8

        self.compactly = True
        self.escape_unicode = False
        self.allow_or_warn_behaviors = frozenset()
        self.indent_amount = 2
        self.indent_tab_width = 0
        self.indent_limit = None
        self.date_format = 'iso'
        self.html_safe = False
        self.keep_format = False
        self.warnings = True
        self.decimal_context = None

        return self

    def copy(self):
        """复制配置对象."""
        other = json_options()
        other.copy_from(self)

        return other

    def copy_from(self, other):
        """从另外一个配置对象复制."""
        self.__dict__.update({k: v for k, v in other.__dict__.items()})

        return self

    def spaces_to_next_indent_level(self, min_spaces=1, subtract=0):
        """下一级缩进的空格数."""
        return max(min_spaces, self.indent_amount - subtract)

    def indentation_for_level(self, level=0):
        """Returns a whitespace string used for indenting."""
        if self.compactly:
            return ''

        limit = self.indent_limit

        if limit is not None:
            level = min(level, limit)

        return ' ' * (level * self.indent_amount)

    def set_indent(self, num_spaces, tab_width=0, limit=None):
        """Changes the indentation properties."""
        self.indent_amount = num_spaces
        self.indent_tab_width = tab_width
        self.indent_limit = limit
        self.compactly = not num_spaces

        return self

    @property
    def sort_keys(self):
        """The method used to sort dictionary keys when encoding JSON."""
        return self._sort_keys

    @sort_keys.setter
    def sort_keys(self, method):
        self._sort_keys = method

    @property
    def encode_enum_as(self):
        """The strategy for encoding Python Enum values."""
        return self._encode_enum_as

    @encode_enum_as.setter
    def encode_enum_as(self, val):
        if val not in ('name', 'qname', 'value'):
            raise ValueError("encode_enum_as must be one of 'name','qname', or 'value'")

        self._encode_enum_as = val

    @property
    def zero_float(self):
        """The numeric value 0.0."""
        return 0.0

    @property
    def negzero_float(self):
        """The numeric value -0.0."""
        return -0.0

    @property
    def nan(self):
        """The numeric value NaN."""
        return nan

    @property
    def inf(self):
        """The numeric value Infinity."""
        return inf

    @property
    def neginf(self):
        """The numeric value -Infinity."""
        return neginf

    def make_int(self, s, sign=None, number_format=NUMBER_FORMAT_DECIMAL):
        """Makes an integer value according to the current options."""
        if isinstance(s, str):
            radix = {
                NUMBER_FORMAT_HEX: 16,
                NUMBER_FORMAT_OCTAL: 8,
                NUMBER_FORMAT_LEGACYOCTAL: 8,
                NUMBER_FORMAT_BINARY: 2,
            }.get(number_format, 10)

            value = int(s, radix)
        else:
            value = int(s)

        if sign == '-':
            value = -value

        return json_int(value, number_format=number_format)

    def make_decimal(self, s, sign='+'):
        """Converts a string into a decimal or float value."""
        import decimal

        value = decimal.Decimal(s)

        return -value if sign == '-' else value

    def make_float(self, s, sign='+'):
        """Converts a string into a float or decimal value."""
        value = float(s)

        return -value if sign == '-' else value

    @property
    def leading_zero_radix(self):
        """The radix to be used for numbers with leading zeros. 8 or 10."""
        return self._leading_zero_radix

    @leading_zero_radix.setter
    def leading_zero_radix(self, radix):
        if int(radix) not in (8, 10):
            raise ValueError('leading_zero_radix must be 8 or 10')

        self._leading_zero_radix = int(radix)

    @property
    def leading_zero_radix_as_word(self):
        """The radix name for numbers with leading zeros."""
        return {8: 'octal', 10: 'decimal'}[self._leading_zero_radix]

    def suppress_warnings(self):
        """关闭警告."""
        self.warnings = False

        return self

    @property
    def strictness(self):
        """严格模式."""
        return self._strictness

    @strictness.setter
    def strictness(self, strict):
        if strict is True:
            self._strictness = STRICTNESS_STRICT
        elif strict is False:
            self._strictness = STRICTNESS_TOLERANT
        else:
            self._strictness = strict


